"""Strict dates, month arithmetic and periods."""
import re
from datetime import date, datetime, timedelta

from tallybook.errors import ParseError


class DateError(ParseError):
    pass


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date '%s': not text" % (text,))
    m = _DATE.fullmatch(text)
    if m is None:
        raise DateError("invalid date '%s': write YYYY-MM-DD" % text)
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text)


def format_date(d):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers")
    if not 1 <= year <= 9999 or not 1 <= month <= 12:
        raise DateError("no such month: %s-%s" % (year, month))
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(d, n):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not _is_int(n):
        raise DateError("months must be a whole number, not %r" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    year, month = divmod(total, 12)
    month += 1
    if not 1 <= year <= 9999:
        raise DateError("date out of range: %s moved by %d months" % (format_date(d), n))
    return date(year, month, min(d.day, last_day(year, month)))


_YEAR = re.compile(r"([0-9]{4})")
_MONTH = re.compile(r"([0-9]{4})-([0-9]{2})")
_QUARTER = re.compile(r"([0-9]{4})-Q([1-4])")
_RANGE = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})")


class Period:
    __slots__ = ("_start", "_end")

    def __init__(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise DateError("a period needs two dates, not %r and %r" % (start, end))
        if end < start:
            raise DateError("empty period: %s ends before %s" % (format_date(end), format_date(start)))
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)

    def __setattr__(self, name, value):
        raise AttributeError("Period is immutable")

    start = property(lambda self: self._start)
    end = property(lambda self: self._end)

    def __eq__(self, other):
        return isinstance(other, Period) and self._start == other._start and self._end == other._end

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._start, self._end))

    def __repr__(self):
        return "Period(%r, %r)" % (self._start, self._end)

    def __str__(self):
        return self.label

    def contains(self, d):
        if not _is_date(d):
            raise DateError("not a date: %r" % (d,))
        return self._start <= d <= self._end

    @property
    def days(self):
        return (self._end - self._start).days + 1

    @property
    def label(self):
        s, e = self._start, self._end
        if s.day == 1 and e.year == s.year:
            if s.month == 1 and e.month == 12 and e.day == 31:
                return "%04d" % s.year
            if s.month in (1, 4, 7, 10) and e.month == s.month + 2 and e.day == last_day(e.year, e.month):
                return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
            if e.month == s.month and e.day == last_day(s.year, s.month):
                return "%04d-%02d" % (s.year, s.month)
        return "%s..%s" % (format_date(s), format_date(e))

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period '%s': not text" % (text,))
        try:
            m = _YEAR.fullmatch(text)
            if m:
                y = int(text)
                return cls(date(y, 1, 1), date(y, 12, 31))
            m = _MONTH.fullmatch(text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(date(y, mo, 1), date(y, mo, last_day(y, mo)))
            m = _QUARTER.fullmatch(text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                first = (q - 1) * 3 + 1
                return cls(date(y, first, 1), date(y, first + 2, last_day(y, first + 2)))
            m = _RANGE.fullmatch(text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (DateError, ValueError) as err:
            raise DateError("invalid period '%s': %s" % (text, err))
        raise DateError("invalid period '%s': write 2024, 2024-03, 2024-Q1 or 2024-03-01..2024-03-31" % text)

    def next(self):
        s, e = self._start, self._end
        try:
            label = self.label
            if len(label) == 4:
                return Period(date(s.year + 1, 1, 1), date(s.year + 1, 12, 31))
            if len(label) == 7 and label[5] == "Q":
                first = s.month + 3
                year = s.year
                if first > 12:
                    first, year = 1, year + 1
                return Period(date(year, first, 1), date(year, first + 2, last_day(year, first + 2)))
            if len(label) == 7:
                nxt = add_months(s, 1)
                return Period(nxt, date(nxt.year, nxt.month, last_day(nxt.year, nxt.month)))
            start = e + timedelta(days=1)
            return Period(start, start + timedelta(days=self.days - 1))
        except (ValueError, OverflowError):
            raise DateError("no period after %s" % self.label)


_STEPS = ("week", "month", "quarter", "year")


def _containing(d, step):
    if step == "week":
        monday = d - timedelta(days=d.weekday())
        return Period(monday, monday + timedelta(days=6))
    if step == "month":
        return Period(date(d.year, d.month, 1), date(d.year, d.month, last_day(d.year, d.month)))
    if step == "quarter":
        first = (d.month - 1) // 3 * 3 + 1
        return Period(date(d.year, first, 1), date(d.year, first + 2, last_day(d.year, first + 2)))
    return Period(date(d.year, 1, 1), date(d.year, 12, 31))


def periods(start, end, step):
    if not _is_date(start) or not _is_date(end):
        raise DateError("periods needs two dates")
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step '%s': use week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("%s is before %s" % (format_date(end), format_date(start)))
    try:
        p = _containing(start, step)
        out = [p]
        while p.end < end:
            p = p.next()
            out.append(p)
    except (ValueError, OverflowError):
        raise DateError("periods run past the end of the calendar")
    return out

